#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    sort(p.rbegin(), p.rend());

    long long total = 0;
    for (int i = 0; i < n; ++i) {
        if ((i + 1) % 3 != 0) {
            total += p[i];
        }
    }

    cout << total << "\n";

